<template>
  <div class="operaciones-page">
    <v-card class="operaciones-header mb-5 rounded-xl" elevation="0" border><v-card-text class="pa-5"><div class="d-flex align-center flex-wrap ga-3"><v-avatar color="primary" variant="tonal" size="48" rounded="lg"><v-icon size="28">mdi-cart-outline</v-icon></v-avatar><div><div class="text-h6 font-weight-bold">Ventas</div><div class="text-body-2 text-medium-emphasis">Ventas al contado y crédito con salida automática de inventario</div></div><v-spacer/><v-chip color="primary" variant="tonal">{{ branch.sucursalActual?.nombre||'Sin sucursal' }}</v-chip><v-btn v-if="canManage&&openBox" color="primary" prepend-icon="mdi-cart-plus" rounded="lg" @click="openCreate">Nueva venta</v-btn></div></v-card-text></v-card>
    <v-alert v-if="error" type="error" variant="tonal" closable class="mb-4" @click:close="error=''">{{ error }}</v-alert><v-alert v-if="branch.idSucursalActual&&!openBox" type="warning" variant="tonal" class="mb-4">Abre la caja para poder registrar ventas.</v-alert>
    <v-row class="mb-3"><v-col cols="12" sm="4"><v-card class="operaciones-metric rounded-xl" border elevation="0"><v-card-text><div class="text-caption text-medium-emphasis">Ventas mostradas</div><div class="text-h5 font-weight-bold mt-2">{{ total }}</div></v-card-text></v-card></v-col><v-col cols="12" sm="4"><v-card class="operaciones-metric rounded-xl" border elevation="0"><v-card-text><div class="text-caption text-medium-emphasis">Monto de la página</div><div class="text-h5 font-weight-bold money mt-2">{{ money(pageTotal) }}</div></v-card-text></v-card></v-col><v-col cols="12" sm="4"><v-card class="operaciones-metric rounded-xl" border elevation="0"><v-card-text><div class="text-caption text-medium-emphasis">Ventas a crédito</div><div class="text-h5 font-weight-bold mt-2">{{ items.filter(x=>x.deudaOriginada).length }}</div></v-card-text></v-card></v-col></v-row>
    <v-card rounded="xl" elevation="0" border class="overflow-hidden"><div class="pa-4 operaciones-toolbar"><v-text-field v-model="search" class="operaciones-search" placeholder="Buscar por detalle o cliente..." prepend-inner-icon="mdi-magnify" variant="outlined" density="comfortable" rounded="lg" hide-details clearable @keyup.enter="searchNow"/><v-btn color="primary" variant="tonal" prepend-icon="mdi-magnify" @click="searchNow">Buscar</v-btn><v-btn icon="mdi-refresh" color="primary" variant="tonal" :loading="loading" @click="load"/></div><v-divider/><div v-if="loading" class="text-center py-14"><v-progress-circular indeterminate color="primary"/></div><template v-else-if="items.length"><v-table hover class="operaciones-table operaciones-desktop"><thead><tr><th>Venta</th><th>Fecha</th><th>Productos</th><th>Cliente / modalidad</th><th>Pagado</th><th class="text-end">Total</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.idIngreso"><td>#{{ item.idIngreso }}</td><td>{{ dateTime(item.fechaIngreso) }}</td><td>{{ item.productos.length }} producto(s)</td><td>{{ item.deudaOriginada?.cliente?.nombre||'Contado' }}</td><td>{{ money(sumPayments(item)) }}</td><td class="text-end font-weight-bold money">{{ money(item.monto) }}</td><td><v-btn icon="mdi-eye-outline" variant="text" color="primary" @click="showDetail(item)"/></td></tr></tbody></v-table><div class="operaciones-mobile pa-3"><v-card v-for="item in items" :key="item.idIngreso" variant="outlined" rounded="lg" class="mb-3" @click="showDetail(item)"><v-card-text><div class="d-flex"><strong>Venta #{{ item.idIngreso }}</strong><v-spacer/><strong>{{ money(item.monto) }}</strong></div><div class="text-caption text-medium-emphasis mt-2">{{ dateTime(item.fechaIngreso) }} · {{ item.productos.length }} producto(s)</div><v-chip v-if="item.deudaOriginada" size="x-small" color="warning" class="mt-2">Crédito</v-chip></v-card-text></v-card></div></template><div v-else class="operaciones-empty"><v-icon size="50">mdi-cart-outline</v-icon><div class="mt-2">No se encontraron ventas</div></div><v-divider/><div class="d-flex align-center justify-space-between pa-3"><span class="text-caption">Mostrando {{ items.length }} de {{ total }}</span><v-pagination v-if="total>limit" v-model="page" :length="Math.ceil(total/limit)" size="small"/></div></v-card>

    <v-dialog v-model="dialog" max-width="980" persistent scrollable><v-card rounded="xl"><v-card-title class="operaciones-dialog-title"><span class="operaciones-dialog-icon"><v-icon>mdi-cart-plus</v-icon></span>Nueva venta<v-spacer/><v-btn icon="mdi-close" variant="text" color="on-primary" @click="dialog=false"/></v-card-title><v-card-text class="pa-5"><v-alert v-if="formError" type="error" variant="tonal" class="mb-4">{{ formError }}</v-alert><div class="d-flex align-center mb-3"><div class="text-subtitle-1 font-weight-bold">Productos</div><v-spacer/><v-btn size="small" color="primary" variant="tonal" prepend-icon="mdi-plus" @click="addLine">Agregar producto</v-btn></div><div v-for="(line,index) in lines" :key="index" class="linea-card"><div class="d-flex ga-3 flex-wrap align-start"><v-autocomplete v-model="line.idProductoSucursal" :items="availableProducts(index)" item-title="producto.nombre" item-value="idProductoSucursal" label="Producto" variant="outlined" density="comfortable" class="flex-grow-1" min-width="250" @update:model-value="setProductPrice(line)"/><v-select v-model="line.idAlmacen" :items="warehouses" item-title="nombre" item-value="idAlmacen" label="Área de salida" variant="outlined" density="comfortable" style="min-width:190px"/><v-text-field v-model="line.cantidad" label="Cantidad" type="number" min="0.001" step="0.001" variant="outlined" density="comfortable" style="max-width:130px"/><v-text-field v-model="line.precioUnitario" label="Precio unitario" prefix="S/" type="number" min="0.0001" step="0.0001" variant="outlined" density="comfortable" style="max-width:170px"/><v-btn icon="mdi-delete-outline" color="error" variant="text" class="mt-1" @click="lines.splice(index,1)"/></div><div class="text-end text-body-2">Subtotal: <strong>{{ money(lineTotal(line)) }}</strong></div></div><v-divider class="my-4"/><v-row><v-col cols="12" md="7"><label class="operaciones-field-label">Detalle</label><v-textarea v-model="form.detail" rows="2" maxlength="500" variant="outlined"/><PagosEditor v-model="payments" :medios="paymentMethods"/></v-col><v-col cols="12" md="5"><v-card variant="tonal" color="primary" rounded="lg" class="mb-4"><v-card-text><div class="d-flex"><span>Total</span><v-spacer/><strong class="text-h6">{{ money(saleTotal) }}</strong></div><div class="d-flex mt-2"><span>Pagado</span><v-spacer/><strong>{{ money(paidTotal) }}</strong></div><v-divider class="my-2"/><div class="d-flex"><span>Saldo a crédito</span><v-spacer/><strong>{{ money(creditBalance) }}</strong></div></v-card-text></v-card><template v-if="creditBalance>0"><label class="operaciones-field-label">Cliente *</label><v-autocomplete v-model="form.clientId" :items="clients" item-title="nombre" item-value="id" variant="outlined"/><label class="operaciones-field-label">Fecha de vencimiento</label><v-text-field v-model="form.dueDate" type="date" variant="outlined"/></template></v-col></v-row></v-card-text><v-divider/><v-card-actions class="pa-4"><v-spacer/><v-btn variant="text" @click="dialog=false">Cancelar</v-btn><v-btn color="primary" :loading="saving" @click="save">Registrar venta</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog :model-value="!!selected" max-width="760" @update:model-value="selected=null"><v-card v-if="selected" rounded="xl"><v-card-title class="pa-5 d-flex">Venta #{{ selected.idIngreso }}<v-spacer/><v-chip v-if="selected.deudaOriginada" color="warning" variant="tonal">A crédito</v-chip></v-card-title><v-card-text class="px-5 pb-5"><div class="text-body-2 text-medium-emphasis mb-4">{{ dateTime(selected.fechaIngreso) }} · {{ selected.detalle||'Sin detalle' }}</div><v-table density="compact"><thead><tr><th>Producto</th><th>Cantidad</th><th>P. unitario</th><th class="text-end">Subtotal</th></tr></thead><tbody><tr v-for="p in selected.productos" :key="`${p.idProductoSucursal}-${p.idAlmacen}`"><td>{{ p.productoSucursal.producto.nombre }}</td><td>{{ p.cantidad }}</td><td>{{ money(p.precioUnitario) }}</td><td class="text-end">{{ money(Number(p.cantidad)*Number(p.precioUnitario)) }}</td></tr></tbody></v-table><div class="text-h6 text-end mt-4">Total: {{ money(selected.monto) }}</div></v-card-text><v-card-actions><v-spacer/><v-btn variant="text" color="primary" @click="selected=null">Cerrar</v-btn></v-card-actions></v-card></v-dialog><v-snackbar v-model="notice" color="success">Venta registrada correctamente</v-snackbar>
  </div>
</template>
<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { getApiErrorMessage } from '@/core/api/api-error'
import { mediosPagoApi, personasApi } from '@/core/api/administracion.api'
import { Permiso } from '@/core/constants/permisos'
import type { MedioPago, PersonaRegistro } from '@/core/types/administracion.types'
import { useAuthStore } from '@/modules/auth/auth.store'
import { almacenesApi, productoSucursalApi } from '@/modules/logistica/logistica.api'
import type { Almacen, ProductoSucursal } from '@/modules/logistica/logistica.types'
import { useSucursalStore } from '@/shared/stores/sucursal.store'
import PagosEditor from '../components/PagosEditor.vue'
import { cajasApi, ventasApi } from '../operaciones.api'
import type { Caja, Ingreso, PagoPayload } from '../operaciones.types'
import '../operaciones.css'
const operationKey = ref('')
interface SaleLine{idProductoSucursal:number|null;idAlmacen:number|null;cantidad:string;precioUnitario:string}
const auth=useAuthStore(),branch=useSucursalStore(),canManage=computed(()=>auth.puede(Permiso.VENTAS_GESTIONAR)),items=ref<Ingreso[]>([]),selected=ref<Ingreso|null>(null),openBox=ref<Caja|null>(null),products=ref<ProductoSucursal[]>([]),warehouses=ref<Almacen[]>([]),clients=ref<PersonaRegistro[]>([]),paymentMethods=ref<MedioPago[]>([]),lines=ref<SaleLine[]>([]),payments=ref<PagoPayload[]>([]),search=ref(''),page=ref(1),limit=30,total=ref(0),loading=ref(false),saving=ref(false),dialog=ref(false),error=ref(''),formError=ref(''),notice=ref(false),form=reactive({detail:'',clientId:null as number|null,dueDate:''})
const pageTotal=computed(()=>items.value.reduce((s,x)=>s+Number(x.monto),0)),saleTotal=computed(()=>lines.value.reduce((s,x)=>s+lineTotal(x),0)),paidTotal=computed(()=>payments.value.reduce((s,x)=>s+Number(x.monto||0),0)),creditBalance=computed(()=>Math.max(0,Math.round((saleTotal.value-paidTotal.value)*100)/100))
async function load(){if(!branch.idSucursalActual){items.value=[];return}loading.value=true;error.value='';try{const response=await ventasApi.listar({idSucursal:branch.idSucursalActual,pagina:page.value,limite:limit,buscar:search.value.trim()||undefined});items.value=response.data.data;total.value=response.data.total;try{openBox.value=(await cajasApi.abierta(branch.idSucursalActual)).data}catch{openBox.value=null}}catch(cause){error.value=getApiErrorMessage(cause,'No se pudieron cargar las ventas')}finally{loading.value=false}}
async function loadFormData(){if(!branch.idSucursalActual)return;const [p,w,c,m]=await Promise.all([productoSucursalApi.listar({idSucursal:branch.idSucursalActual,estado:true,limite:100}),almacenesApi.listar({idSucursal:branch.idSucursalActual,estado:true,limite:100}),personasApi.listar('CLIENTE'),mediosPagoApi.listar()]);products.value=p.data.data;warehouses.value=w.data.data;clients.value=c.data.filter(x=>x.activo);paymentMethods.value=m.data}
async function openCreate(){operationKey.value=crypto.randomUUID();lines.value=[];payments.value=[];Object.assign(form,{detail:'',clientId:null,dueDate:''});formError.value='';addLine();dialog.value=true;try{await loadFormData()}catch(cause){formError.value=getApiErrorMessage(cause,'No se pudieron cargar los catálogos')}}function addLine(){lines.value.push({idProductoSucursal:null,idAlmacen:null,cantidad:'1',precioUnitario:''})}function availableProducts(index:number){const used=new Set(lines.value.filter((_,i)=>i!==index).map(x=>x.idProductoSucursal));return products.value.filter(x=>!used.has(x.idProductoSucursal))}function setProductPrice(line:SaleLine){const found=products.value.find(x=>x.idProductoSucursal===line.idProductoSucursal);if(found)line.precioUnitario=found.precioVenta}function lineTotal(line:SaleLine){return (Number(line.cantidad)||0)*(Number(line.precioUnitario)||0)}
async function save(){if(saving.value)return;if(!openBox.value||!branch.idSucursalActual)return;if(!lines.value.length||lines.value.some(x=>!x.idProductoSucursal||!x.idAlmacen||lineTotal(x)<=0)){formError.value='Completa todos los productos, cantidades, precios y áreas de salida';return}if(paidTotal.value>saleTotal.value+.001){formError.value='El pago no puede superar el total';return}if(creditBalance.value>0&&!form.clientId){formError.value='Selecciona el cliente para la venta a crédito';return}saving.value=true;formError.value='';try{await ventasApi.crear({claveOperacion:operationKey.value,idCaja:openBox.value.idCaja,idSucursal:branch.idSucursalActual,monto:saleTotal.value.toFixed(2),detalle:form.detail.trim()||undefined,productos:lines.value.map(x=>({idProductoSucursal:x.idProductoSucursal,idAlmacen:x.idAlmacen,cantidad:Number(x.cantidad).toFixed(3),precioUnitario:Number(x.precioUnitario).toFixed(4)})),pagos:payments.value,...(creditBalance.value>0?{credito:{idCliente:form.clientId,fechaVencimiento:form.dueDate||undefined}}:{})});dialog.value=false;notice.value=true;await load()}catch(cause){formError.value=getApiErrorMessage(cause,'No se pudo registrar la venta')}finally{saving.value=false}}
async function showDetail(item:Ingreso){try{selected.value=(await ventasApi.obtener(item.idIngreso)).data}catch(cause){error.value=getApiErrorMessage(cause)}}function searchNow(){if(page.value!==1)page.value=1;else void load()}function sumPayments(x:Ingreso){return x.pagos.reduce((s,p)=>s+Number(p.monto),0)}function money(v:string|number){return new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(Number(v)||0)}function dateTime(v:string){return new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeStyle:'short'}).format(new Date(v))}
watch([()=>branch.idSucursalActual,page],()=>void load(),{immediate:true})
</script>
